import sys

def solve():
    t = sys.stdin.readline().strip()
    p = sys.stdin.readline().strip()
    a_line = sys.stdin.readline().split()
    n = len(t)
    m = len(p)

    perm = [int(x) - 1 for x in a_line]

    def can_keep(k):
        removed = set()
        for i in range(k):
            removed.add(perm[i])

        j = 0
        for i in range(n):
            if i not in removed:
                if j < m and t[i] == p[j]:
                    j += 1
        return j == m

    low = 0
    high = n - m
    ans = 0

    while low <= high:
        mid = (low + high) // 2
        if can_keep(mid):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    print(ans)

if __name__ == "__main__":
    solve()
